"""Strings.resx에서 강타입 접근자 Strings.Designer.cs를 만든다(3단계).

사용: python tools/resx/gen_designer.py
Visual Studio의 ResXFileCodeGenerator와 같은 역할이다. dotnet CLI만으로는 Designer가 생성되지 않으므로
resx에 항목을 추가·변경한 뒤 이 스크립트를 다시 돌린다.
"""
import xml.etree.ElementTree as ET
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2] / "src" / "MoaView.App" / "Resources"


def main() -> None:
    tree = ET.parse(ROOT / "Strings.resx")
    entries = [(d.get("name"), d.findtext("value") or "") for d in tree.getroot().findall("data")]
    entries.sort()

    out = [
        "// <auto-generated>",
        "//     tools/resx/gen_designer.py가 Strings.resx에서 생성했다. 직접 고치지 말고 resx를 바꾼 뒤 다시 생성한다.",
        "// </auto-generated>",
        "",
        "using System.Globalization;",
        "using System.Resources;",
        "",
        "namespace MoaView.App.Resources;",
        "",
        "/// <summary>UI 문자열 리소스(D-08 다국어 대비, 1차는 한국어). XAML에서는 {x:Static res:Strings.Key}, C#에서는 Strings.Key로 쓴다.</summary>",
        "public static class Strings",
        "{",
        '    private static readonly ResourceManager Manager = new("MoaView.App.Resources.Strings", typeof(Strings).Assembly);',
        "",
        "    /// <summary>null이면 현재 UI 문화권을 따른다.</summary>",
        "    public static CultureInfo? Culture { get; set; }",
        "",
        "    public static string Get(string key) => Manager.GetString(key, Culture) ?? key;",
    ]
    for name, value in entries:
        summary = value.replace("\n", " ").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        if len(summary) > 100:
            summary = summary[:97] + "..."
        out.append("")
        out.append(f"    /// <summary>{summary}</summary>")
        out.append(f'    public static string {name} => Get("{name}");')
    out.append("}")
    (ROOT / "Strings.Designer.cs").write_text("\n".join(out) + "\n", encoding="utf-8")
    print(f"Designer 속성 {len(entries)}개 생성")


if __name__ == "__main__":
    main()
